import{_ as o,o as u,c as q,ag as r}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"05 股市交易与币圈——10篇天涯神贴精读笔记","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/05_股市交易与币圈.md","filePath":"topics/tianya/notes/05_股市交易与币圈.md"}'),n={name:"topics/tianya/notes/05_股市交易与币圈.md"};function s(a,t,g,p,e,i){return u(),q("div",null,[...t[0]||(t[0]=[r('<h1 id="_05-股市交易与币圈——10篇天涯神贴精读笔记" tabindex="-1">05 股市交易与币圈——10篇天涯神贴精读笔记 <a class="header-anchor" href="#_05-股市交易与币圈——10篇天涯神贴精读笔记" aria-label="Permalink to &quot;05 股市交易与币圈——10篇天涯神贴精读笔记&quot;">​</a></h1><h2 id="_1-南侠1987《两次杠杆做到5000万股灾被强平的投机之路》-2015-10—2016" tabindex="-1">1. 南侠1987《两次杠杆做到5000万股灾被强平的投机之路》（2015.10—2016） <a class="header-anchor" href="#_1-南侠1987《两次杠杆做到5000万股灾被强平的投机之路》-2015-10—2016" aria-label="Permalink to &quot;1. 南侠1987《两次杠杆做到5000万股灾被强平的投机之路》（2015.10—2016）&quot;">​</a></h2><p><strong>作者与年代</strong>：28岁开帖，湖南草根，2012年因追天涯股票小说帖入市。</p><p><strong>主线</strong>：2014年底满仓加4倍配资搏券商股，遇&quot;119股灾&quot;（1·19两融检查券商集体跌停），2100万自有资金被强平到70万；半年后以70万高杠杆利滚利做到2000多万、巅峰5000万，上过龙虎榜。随后刻意降杠杆、分散龙二龙三、留30%防御仓、备600万应急资金，自认&quot;固若金汤&quot;，却在2015年6—8月两波千股跌停中防线尽毁，最终爆仓。</p><p><strong>方法论与教训</strong>：在西部证券一只股上花2500小时、交易额数亿，仍躲不过系统性崩盘；个股技术是&quot;剑法&quot;，大盘趋势是&quot;内功&quot;，他三次下跌均满仓硬抗；配资公司统计：几千个客户不收手者&quot;结局都差不多——均以爆仓为告终&quot;。</p><p><strong>金句</strong>：&quot;天堂跟地狱之间，并不遥远，一念之差&quot;；&quot;赤手空拳苦练盖世神功，怎敌手握核武器的皇族资金？&quot;</p><p><strong>结局</strong>：自认赌性重、财富管理失败，&quot;斩仓&quot;离开股市，出电子书《流血的股市》，纸质书因股灾内容敏感难产。</p><h2 id="_2-1199174《三十三岁-16年股龄-记录自己的心情》-2011—2019" tabindex="-1">2. 1199174《三十三岁，16年股龄，记录自己的心情》（2011—2019） <a class="header-anchor" href="#_2-1199174《三十三岁-16年股龄-记录自己的心情》-2011—2019" aria-label="Permalink to &quot;2. 1199174《三十三岁，16年股龄，记录自己的心情》（2011—2019）&quot;">​</a></h2><p><strong>作者与年代</strong>：2011年开帖，1995年入市，职业短线客+股指期货日内交易者，后自称&quot;数字哥&quot;。</p><p><strong>主线</strong>：自报当年盈利近1000万，黄金200手空单一天浮盈334万；贴期指实盘单，一天6轮高抛低吸赚62万，&quot;这样的方法已让我很多年不知道什么是亏损&quot;。技术底子：缠论&quot;前10章就够&quot;，MACD默认参数、分钟级顶底背离共振定当日基调。帖子遭人恶意刷屏捣乱，曾愤而退帖。</p><p><strong>方法论</strong>：&quot;中线选股，短线操作，滚动利润&quot;；底部&quot;从高往低买，主动带套&quot;；买股的理由不是&quot;很好&quot;而是&quot;该买&quot;；&quot;技术是稳定持续盈利的方法，不是应对极端情况的方法&quot;。</p><p><strong>金句</strong>：&quot;股市赚钱，功夫在股外&quot;。</p><p><strong>结局</strong>：更新至2019年，转公众号写《23年老股民系列》，广告收入遭恶意举报被封20年；晚年&quot;每天看盘不超过5分钟&quot;。实盘无从审计，但&quot;心态与技术缺一不可&quot;贯穿全帖。</p><h2 id="_3-岑若曦《短线的最高境界是不停的追逐涨停》-2015-6—2020" tabindex="-1">3. 岑若曦《短线的最高境界是不停的追逐涨停》（2015.6—2020+） <a class="header-anchor" href="#_3-岑若曦《短线的最高境界是不停的追逐涨停》-2015-6—2020" aria-label="Permalink to &quot;3. 岑若曦《短线的最高境界是不停的追逐涨停》（2015.6—2020+）&quot;">​</a></h2><p><strong>作者与年代</strong>：2007年入市，开帖恰在股灾前一周，写到2020年2月后，51万楼。</p><p><strong>主线与方法</strong>：只做涨停过的强势股，&quot;研究涨停就是研究主力心理学&quot;；只参与拉升段，卖出即交易结束；成功率70%+、复利递增、最多3只股；只做&quot;最强&quot;板块龙头，&quot;银行石油只能躲雨，不能赚钱，救大盘的只能是热点&quot;；&quot;宁可错过，不能做错&quot;。</p><p><strong>实盘检验</strong>：开帖即遇股灾，7·27创8年最大跌幅，自认&quot;再牛的个股也扛不住大盘&quot;；2015年靠热点轮动（猪肉、高送转、军工）加止损纪律熬过；2020年2月满手芯片半导体，&quot;在能涨的板块里找好股，比在废物堆里找精品容易得多&quot;。</p><p><strong>金句</strong>：&quot;持股10天赚30%，与10天做10只股各赚3%效果一样，后者利润更大，因为有复利&quot;。</p><p><strong>结局</strong>：少数活过股灾的短线客，靠纪律存活至今；但胜率与收益无法审计，帖内&quot;必解套&quot;式口头承诺亦暴露跟单咨询局限。</p><h2 id="_4-peterwind-phding《空——以期货实盘讲什么是-道-》-2015—2018" tabindex="-1">4. peterwind_PhDing《空——以期货实盘讲什么是&quot;道&quot;》（2015—2018） <a class="header-anchor" href="#_4-peterwind-phding《空——以期货实盘讲什么是-道-》-2015—2018" aria-label="Permalink to &quot;4. peterwind_PhDing《空——以期货实盘讲什么是&quot;道&quot;》（2015—2018）&quot;">​</a></h2><p><strong>作者与年代</strong>：2015年3月开帖。计算机本科+MBA+AI博士，曾任电信、Intel中高管，因家乡地震看破生死，做慈善后赴荷兰读博。</p><p><strong>主线</strong>：以《易经》讲市场——简易、变易、不易，市场只是多空两种力量在变。期货实盘：3万本金一个月翻倍到6万，先取走一半盈利。<strong>大突破策略</strong>：模糊集合定义&quot;大&quot;，只做时空明确的大趋势；开单需斜率、关键位、二次突破、量能与MACD/KDJ/BOLL共振；仓位=状态（多/空/震荡）×级别；止盈用斐波那契时间周期+马尔科夫关键位。</p><p><strong>心法</strong>：&quot;期货一定要轻仓交易，永远不重仓&quot;；一年只抓几次大机会，季度抓一次、每次10%仓位，年收益即可超40%；交易之道只有一个字&quot;空&quot;——放空自己、追随趋势，&quot;重要的是追随趋势，而不是预测趋势&quot;。</p><p><strong>金句</strong>：&quot;顶底多反复——没有疯狂的来回震荡，这里就不会是顶底&quot;。</p><p><strong>结局</strong>：2018年帖子转为诗词美食生活贴，理论沉淀为&quot;空论&quot;。唯一把轻仓+系统化讲透的人，但玄学漫谈浓重，实盘样本仅几十手。</p><h2 id="_5-时代之《市场心理研究——贪嗔痴慢疑》-2015-2—2016" tabindex="-1">5. 时代之《市场心理研究——贪嗔痴慢疑》（2015.2—2016） <a class="header-anchor" href="#_5-时代之《市场心理研究——贪嗔痴慢疑》-2015-2—2016" aria-label="Permalink to &quot;5. 时代之《市场心理研究——贪嗔痴慢疑》（2015.2—2016）&quot;">​</a></h2><p><strong>作者与年代</strong>：自称&quot;专业搞心理的&quot;，每日结合心理学与行情分析。</p><p><strong>主线</strong>：以卡尼曼前景理论点破散户三大通病：损失厌恶导致&quot;被套不割肉、牛市拿不住、熊市装死&quot;；贪嗔痴慢疑对应市场情绪，&quot;贪婪不一定是坏事，但必须能控制贪欲&quot;；技术指标门槛在统计——回测须含交易成本与滑点，否则只是巧合；程序化也救不了心态（朋友实盘遇回撤后拔电源人工止损）。2015年4月提示牛市临近终结，股灾后坚定翻空。</p><p><strong>实盘</strong>：2016年公布三大策略——做空股市、做空汇市、做多黄金，退欧日称&quot;完美兑现&quot;，自报市值7倍增长；天天盯国家队持仓（&quot;现身1400多家公司，市值两万多亿&quot;）。</p><p><strong>金句</strong>：&quot;有一种痛，叫炒股炒成股东；有一种梦，叫救市救成大股东&quot;。</p><p><strong>结局</strong>：与网友对骂后2016年5月怒而弃帖转公众号。方向押中，但&quot;7倍收益&quot;无实盘凭证，其暴怒恰是对自家&quot;贪嗔&quot;理论的讽刺注脚。</p><h2 id="_6-背上痒难受《赌场二年》-2008—2009" tabindex="-1">6. 背上痒难受《赌场二年》（2008—2009） <a class="header-anchor" href="#_6-背上痒难受《赌场二年》-2008—2009" aria-label="Permalink to &quot;6. 背上痒难受《赌场二年》（2008—2009）&quot;">​</a></h2><p><strong>作者与年代</strong>：在地下赌场干过车夫、荷官、二管、码队、庄家、望风等全部工种，还入了小股。</p><p><strong>主线</strong>：系统展示地下赌场生态——抽水5%—10%；赌场自称&quot;公司&quot;，场租日付200—500元，&quot;地税国税&quot;都交；自己人轮番上场&quot;冲气氛&quot;，注码可输水子必赚；每天提留3000元专供被抓后&quot;平事捞人&quot;；记录&quot;栽花&quot;等出千手法与码队催债、跑路、&quot;被伤身&quot;链条；作者本人从有积蓄到一文不名、负债累累，朋友倾家荡产妻离子散；并写出狱人员&quot;好人学得更坏，牢友结伙把损失夺回来&quot;的生态。</p><p><strong>结论</strong>：赌场里稳定盈利的只有开场的和出千的，赌徒任何&quot;系统&quot;都敌不过抽水+出千+暴力催收。</p><p><strong>金句</strong>：&quot;十赌九诈，其实应该是十赌十诈&quot;；&quot;吃不穷嫖不穷，抽的穷赌的穷&quot;。</p><p><strong>结局</strong>：2009年5月完结。作者自剖&quot;常在岸边走，还站在了水里&quot;，写帖只为警醒世人。</p><h2 id="_7-揭育润《赌坛风云——还你一个真实的老千世界》-2011—2018" tabindex="-1">7. 揭育润《赌坛风云——还你一个真实的老千世界》（2011—2018） <a class="header-anchor" href="#_7-揭育润《赌坛风云——还你一个真实的老千世界》-2011—2018" aria-label="Permalink to &quot;7. 揭育润《赌坛风云——还你一个真实的老千世界》（2011—2018）&quot;">​</a></h2><p><strong>作者与年代</strong>：职业老千20余年，自称赢过几亿、分得上亿，全输回赌场；转行四次又输光重操旧业。2008年参加反赌活动后决意写书。</p><p><strong>核心论点</strong>：千术分两块——技术是&quot;武&quot;，背后运作是&quot;文&quot;，<strong>真正拿命的是千局背后的布局</strong>，&quot;定江山靠的是文&quot;；高端局重布局（挑人挑场，技术要求反而低），低端散场重技术；老千既设计别人也被别人设计，做局须让对手分不清哪手出千哪手赌运气；赌场能赚钱的只有开赌场的和老千；自剖负罪感：最恨坑蒙拐骗，却靠骗赌徒为生。</p><p><strong>金句</strong>：&quot;赌博从来就是只有地狱，没有天堂的游戏&quot;；&quot;能把骗局揭露出来，就已证明我的反赌决心，比空洞说教实在&quot;。</p><p><strong>结局</strong>：帖子更至2018年后（32万楼），作者自认仍有赌瘾，靠写作自救。他把&quot;十赌九输&quot;从道德说教升级为结构分析：抽水、信息差、暴力与法律缺位共同决定赌徒期望必为负。</p><h2 id="_8-冻云迷雾《虚拟货币的秘密-兼谈比特币的未来》-2014—2020" tabindex="-1">8. 冻云迷雾《虚拟货币的秘密，兼谈比特币的未来》（2014—2020） <a class="header-anchor" href="#_8-冻云迷雾《虚拟货币的秘密-兼谈比特币的未来》-2014—2020" aria-label="Permalink to &quot;8. 冻云迷雾《虚拟货币的秘密，兼谈比特币的未来》（2014—2020）&quot;">​</a></h2><p><strong>作者与年代</strong>：2014年5月开帖，宏观货币理论视角，后开收费贴、建群。</p><p><strong>核心论点</strong>：货币演化史=非货币价值递减、货币价值递增（粮食→贝→铜→金银→纸币→数字货币）；数字货币的革命不在无钞流通，而在<strong>发行与信用的创新</strong>——分布式背书终结超级机构垄断；法币背书从来不是免费午餐（举&quot;100元存22年利息不足8元&quot;例），美元霸权更以全球为盘剥对象；比特币可无限分割，不像黄金受&quot;稀少&quot;制约，但有&quot;致命弱点&quot;；预言矿机化、各国严控矿场，惋惜中国挖矿&quot;一骑绝尘却因政策分散&quot;。</p><p><strong>实盘与心法</strong>：2018年熊市反复喊&quot;下跌只是刻意压弹簧，压得越凶将来跳得越高&quot;；告诫粉丝勿碰山寨币和ICO——有老粉重仓山寨币跌十几倍回本无望；2020年断言&quot;黄金回光返照&quot;&quot;央行数字货币才是终局&quot;。</p><p><strong>金句</strong>：&quot;信用和背书只是表象，是社会对货币价值及生产成本综合权衡的结果&quot;。</p><p><strong>结局</strong>：对无钞流通、央行数字货币、矿场监管的预判大体兑现；但后期滑向阴谋论，&quot;收费贴+财富自由承诺&quot;本身即是币圈风险的活标本。</p><h2 id="_9-万里依然《三年挣850万-你也可以复制》-2010—2014-已出版" tabindex="-1">9. 万里依然《三年挣850万，你也可以复制》（2010—2014，已出版） <a class="header-anchor" href="#_9-万里依然《三年挣850万-你也可以复制》-2010—2014-已出版" aria-label="Permalink to &quot;9. 万里依然《三年挣850万，你也可以复制》（2010—2014，已出版）&quot;">​</a></h2><p><strong>作者与年代</strong>：1994年化工大学毕业进京，横跨广告、设计、快消营销，出书《我把一切告诉你》。</p><p><strong>主线</strong>：报社广告员，同期47人只剩他一个；驻扎客户+陪下棋拿下首单；从红牛广告&quot;跑步顺拐&quot;的错误切入签下60万大单成销售状元；攻心为上——每周五打传呼祝周末愉快、信封手写一句话、小本记录客户衣着话题；后转攻4A圈，再创业设计公司（一周背5000张国际设计图），进A集团做广告主管。谈判术：观察摸鼻子等肢体语言、诉苦拆单施压、以60万户外广告置换折扣。</p><p><strong>方法论</strong>：&quot;伤其一指，不如断其一指——把一件事彻底做透&quot;；勤奋+把简单招式练到极致。他自认失败在期货：&quot;对赌期货上栽了大跟头&quot;，并讲湛江糖王白糖期货亏几亿跳楼、次日糖价大涨的故事作风险教育。</p><p><strong>金句</strong>：&quot;三贫三富不到老——没剩下的是身外财富，剩下的是头脑里的本事&quot;。</p><p><strong>结局</strong>：出书成畅销作家；通篇展示&quot;术&quot;，最值钱的恰是那句对杠杆投机代价的旁证。</p><h2 id="_10-目光呆滞的润土《风云-中国第一本企业家自传-》-2005—2019" tabindex="-1">10. 目光呆滞的润土《风云（中国第一本企业家自传）》（2005—2019+） <a class="header-anchor" href="#_10-目光呆滞的润土《风云-中国第一本企业家自传-》-2005—2019" aria-label="Permalink to &quot;10. 目光呆滞的润土《风云（中国第一本企业家自传）》（2005—2019+）&quot;">​</a></h2><p><strong>作者与年代</strong>：18岁进经济机关，拒绝权贵联姻，87年起连续创业。</p><p><strong>主线</strong>：第一次创业卖服装——1万元起家，分析进口西装&quot;日式贴身难做事、英式开叉被讥冒充华侨&quot;的缺陷，设计双排扣不开叉全毛西服，五星商场单日销量第一，4个月1万变10万，因&quot;投机倒把&quot;、无法注册英文商标夭折；第二次做石油——发现&quot;按吨买、按升卖&quot;的油票换算漏洞，1年半5万变100万，败于政策调整；第三次做公交IC卡广告整合，10万做出450万利润，败于合作方毁约、法律不公。后半部转型经济评论：著名的&quot;绵羊经济与华为孤狼论&quot;、&quot;农民利益被牺牲是中国低成本竞争力之源&quot;，并连年发《土哥预测》（2019年&quot;庄家被黑吃黑、越南增速超中国、马云主动退休&quot;）。</p><p><strong>金句</strong>：&quot;发财与事业是两个概念&quot;；&quot;读史使人明智，哲理使人明慧&quot;。</p><p><strong>结局</strong>：三次创业皆败于政策与规则而非市场，得出&quot;在中国做生意先要了解政治与社会规则&quot;——与南侠1987&quot;政策市散户是鱼肉&quot;遥相呼应，是全合集最沉重的暗线。</p><h2 id="总览与心得-这批-用真金白银换来的经验-的共同教训" tabindex="-1">总览与心得：这批&quot;用真金白银换来的经验&quot;的共同教训 <a class="header-anchor" href="#总览与心得-这批-用真金白银换来的经验-的共同教训" aria-label="Permalink to &quot;总览与心得：这批&quot;用真金白银换来的经验&quot;的共同教训&quot;">​</a></h2><ol><li><strong>杠杆是绞肉机，轻仓是活路</strong>。南侠1987两次从千万跌回70万，配资公司&quot;不收手必爆仓&quot;的统计摆在眼前；唯一长期存活的期货楼主peterwind反复念叨&quot;永远不重仓&quot;。同一枚硬币的两面，用两代人的账户余额写成。</li><li><strong>赌与投机的数学期望注定为负</strong>。赌场两篇把抽水、出千、放码、暴力催收讲透：赢的前提被系统性剥夺；股市里的高倍配资、对赌期货（糖王跳楼）只是换了赌桌。老千和赌徒的区别只在：老千知道自己是刀，赌徒以为自己是猎手。</li><li><strong>心态即系统</strong>。时代之点破散户死于损失厌恶——牛市拿不住、熊市装死；万里依然与糖王输的都是心态而非智力。技术只占三成，纪律与情绪管理才是分水岭。</li><li><strong>在中国，政策与规则是第一变量</strong>。润土三次创业败于&quot;投机倒把&quot;与政策转向；南侠叹&quot;敌不过皇族资金&quot;；时代之天天盯国家队。不懂政策周期，技术再精也是&quot;剑法精而内力平平&quot;。</li><li><strong>闷声发财者戒贪，高调兜售者存疑</strong>。持续盈利者展示苦功与系统；晒收益、开收费贴、喊财富自由者，其商业模式本身就是向粉丝收&quot;水子&quot;。听人荐股前，先看他靠什么赚钱。</li><li><strong>幸存者的共同点：把一件事做透，且方向正确</strong>。南侠在一只股上花2500小时仍满仓硬抗，输在方向与风控；岑若曦、peterwind靠纪律与轻仓活下来。<strong>勤奋决定下限，风控与方向决定生死。</strong></li></ol>',61)])])}const _=o(n,[["render",s]]);export{h as __pageData,_ as default};
